import json, os, time, threading
from datetime import datetime, timezone
BASE = os.path.expanduser("~/savant/context")
EVENT_LOG = os.path.join(BASE, "events.log")
SUBSCRIBERS = {}

### — Savant Insight —
# Purpose: utc_now — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:16:09
def utc_now(): return datetime.now(timezone.utc).isoformat()

### — Savant Insight —
# Purpose: publish — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:16:09
def publish(event_type, payload):
    """Record and notify subscribers."""
    entry = {"time": utc_now(), "type": event_type, "payload": payload}
    os.makedirs(BASE, exist_ok=True)
    with open(EVENT_LOG, "a") as f:
        f.write(json.dumps(entry) + "\n")
    for name, callback in SUBSCRIBERS.items():
        try:
            callback(entry)
        except Exception as e:
            print(f"[WARN] Subscriber {name} failed: {e}")
    return entry

### — Savant Insight —
