# Added 2025-10-30 19:16:09
def subscribe(name, callback):
    SUBSCRIBERS[name] = callback
    return {"status": "subscribed", "subscriber": name, "count": len(SUBSCRIBERS)}

### — Savant Insight —
# Purpose: replay_recent — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:16:09
def replay_recent(limit=20):
    if not os.path.exists(EVENT_LOG):
        return []
    lines = open(EVENT_LOG).read().strip().splitlines()[-limit:]
    return [json.loads(l) for l in lines]

### — Savant Insight —
# Purpose: auto_flush — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:16:09
def auto_flush(interval=60):
    """Flush events to rotated archive every minute."""
    def _run():
        while True:
            if os.path.exists(EVENT_LOG) and os.path.getsize(EVENT_LOG) > 5_000_000:
                ts = datetime.now().strftime("%Y%m%d_%H%M%S")
                os.rename(EVENT_LOG, os.path.join(BASE, f"events_{ts}.log"))
            time.sleep(interval)
    t = threading.Thread(target=_run, daemon=True)
    t.start()


